// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "name", "SYM"); }
    function testFuzz_property(uint256 initialMint, uint256 burnAmount) public {
        vm.assume(initialMint > 0);
        vm.assume(burnAmount > 0 && burnAmount <= initialMint);

        c.mintToken(address(this), initialMint);
        uint256 supplyBefore = c.totalSupply();

        c.burn(burnAmount);
        uint256 supplyAfter = c.totalSupply();

        assertTrue(supplyAfter == supplyBefore - burnAmount);
    }
}
